-- Zamenja testne artikle in njihovo testno zgodovino z aktualnim stanjem, ki ste ga poslali.
alter table public.products add column if not exists counting_unit text;
alter table public.products add column if not exists alternative_unit text;
alter table public.products add column if not exists alternative_unit_size numeric(12,3) check (alternative_unit_size > 0);
alter table public.products add column if not exists count_step numeric(12,3) not null default 1 check (count_step > 0);

