drop policy if exists "counts own draft read" on public.inventory_counts;
create policy "counts own read" on public.inventory_counts for select to authenticated using (created_by = auth.uid() or public.is_admin());
drop policy if exists "count items own draft read" on public.inventory_count_items;
create policy "count items own read" on public.inventory_count_items for select to authenticated using (public.is_admin() or exists(select 1 from public.inventory_counts c where c.id = inventory_count_id and c.created_by = auth.uid()));
drop policy if exists "counts delete own draft" on public.inventory_counts;
create policy "counts delete own draft" on public.inventory_counts for delete to authenticated using (public.is_admin() or (created_by = auth.uid() and status = 'draft'));
